#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, long long>>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back({(int)e[1], e[2]});
        adj[e[1]].push_back({(int)e[0], e[2]});
    }
    const long long INF = 1000000000000000000LL;
    vector<vector<long long>> dist(2, vector<long long>(n + 1, INF));
    dist[0][1] = 0;
    typedef pair<long long, pair<int, int>> Item;
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    heap.push({0, {1, 0}});
    while (!heap.empty()) {
        Item top = heap.top();
        heap.pop();
        long long d = top.first;
        int u = top.second.first, used = top.second.second;
        if (d > dist[used][u]) continue;
        for (const auto& edge : adj[u]) {
            int v = edge.first;
            if (d + edge.second < dist[used][v]) {
                dist[used][v] = d + edge.second;
                heap.push({dist[used][v], {v, used}});
            }
            if (used == 0 && d < dist[1][v]) {
                dist[1][v] = d;
                heap.push({d, {v, 1}});
            }
        }
    }
    long long answer = min(dist[0][n], dist[1][n]);
    cout << (answer < INF ? answer : -1) << "\n";

    return 0;
}

